            // A[k, j] -= f * A[c,j] for j>=c
            // since we already know A[k,c] becomes 0, start j=c
            for(int j=c;j<m;j++){
                Ar[k*m+j] = Ar[k*m+j] - (fr*Ar[c*m+j] - fi*Ai[c*m+j]);
                Ai[k*m+j] = Ai[k*m+j] - (fr*Ai[c*m+j] + fi*Ar[c*m+j]);
