                                  double*, double*, double*, long, double*, long);

// complex LU solve (in place) of A x = b. A: Ar,Ai (m*m row-major), b: br,bi (m).
static int cplx_lu_solve(double* Ar, double* Ai, double* br, double* bi, int m) {
    int* piv = (int*)malloc(sizeof(int)*m);
    if(!piv) return -1;
    for(int i=0;i<m;i++) piv[i]=i;
    for(int c=0;c<m;c++){
        int pk=c; double best=-1.0;
        for(int k=c;k<m;k++){ double ar=Ar[k*m+c], ai=Ai[k*m+c]; double v=ar*ar+ai*ai; if(v>best){best=v;pk=k;} }
        if(best < 1e-240){ free(piv); return -1; }
        for(int j=c;j<m;j++){ double t=Ar[c*m+j];Ar[c*m+j]=Ar[pk*m+j];Ar[pk*m+j]=t; t=Ai[c*m+j];Ai[c*m+j]=Ai[pk*m+j];Ai[pk*m+j]=t; }
        { double t=br[c];br[c]=br[pk];br[pk]=t; t=bi[c];bi[c]=bi[pk];bi[pk]=t; }
        int tp=piv[c];piv[c]=piv[pk];piv[pk]=tp;
        for(int k=c+1;k<m;k++){
            double dr=Ar[c*m+c], di=Ai[c*m+c]; double den=dr*dr+di*di;
            double ar=Ar[k*m+c], ai=Ai[k*m+c];
            double fr=(ar*dr+ai*di)/den; double fi=(ai*dr-ar*di)/den;
            for(int j=c;j<m;j++){
                double acr=Ar[c*m+j], aci=Ai[c*m+j];
                Ar[k*m+j]=Ar[k*m+j]-(fr*acr-fi*aci);
                Ai[k*m+j]=Ai[k*m+j]-(fr*aci+fi*acr);
            }
            double brc=br[c], bic=bi[c];
            br[k]=br[k]-(fr*brc-fi*bic);
            bi[k]=bi[k]-(fr*bic+fi*brc);
        }
    }
    for(int k=m-1;k>=0;k--){
        double sr=br[k], si=bi[k];
        for(int j=k+1;j<m;j++){
            double xr=br[j], xi=bi[j]; double acr=Ar[k*m+j], aci=Ai[k*m+j];
            sr=sr-(acr*xr-aci*xi);
            si=si-(acr*xi+aci*xr);
        }
        double dr=Ar[k*m+k], di=Ai[k*m+k]; double den=dr*dr+di*di;
        br[k]=(sr*dr+si*di)/den;
        bi[k]=(si*dr-sr*di)/den;
    }
    free(piv);
    return 0;
}

