#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static const int COL_MAJOR = 101;
extern int scipy_LAPACKE_dgeev64_(int, char, char, long, double*, long,
                                  double*, double*, double*, long, double*, long);

static int cplx_lu_solve(double* Ar, double* Ai, double* br, double* bi, int m) {
    if (m == 0) return 0;
    int* piv = (int*)malloc(sizeof(int) * m);
    if (!piv) return -1;
    for (int i = 0; i < m; i++) piv[i] = i;
    for (int c = 0; c < m; c++) {
        int pk = c; double best = -1.0;
        for (int k = c; k < m; k++) { double ar = Ar[k*m+c], ai = Ai[k*m+c]; double v = ar*ar + ai*ai; if (v > best) { best = v; pk = k; } }
        if (best < 1e-240) { free(piv); return -1; }
        for (int j = c; j < m; j++) { double t = Ar[c*m+j]; Ar[c*m+j] = Ar[pk*m+j]; Ar[pk*m+j] = t; t = Ai[c*m+j]; Ai[c*m+j] = Ai[pk*m+j]; Ai[pk*m+j] = t; }
        { double t = br[c]; br[c] = br[pk]; br[pk] = t; t = bi[c]; bi[c] = bi[pk]; bi[pk] = t; }
        int tp = piv[c]; piv[c] = piv[pk]; piv[pk] = tp;
        for (int k = c + 1; k < m; k++) {
            double dr = Ar[c*m+c], di = Ai[c*m+c]; double den = dr*dr + di*di;
            double ar = Ar[k*m+c], ai = Ai[k*m+c];
            double fr = (ar*dr + ai*di) / den; double fi = (ai*dr - ar*di) / den;
            for (int j = c; j < m; j++) {
                double acr = Ar[c*m+j], aci = Ai[c*m+j];
                Ar[k*m+j] = Ar[k*m+j] - (fr*acr - fi*aci);
                Ai[k*m+j] = Ai[k*m+j] - (fr*aci + fi*acr);
            }
            double brc = br[c], bic = bi[c];
            br[k] = br[k] - (fr*brc - fi*bic);
            bi[k] = bi[k] - (fr*bic + fi*brc);
        }
    }
    for (int k = m - 1; k >= 0; k--) {
        double sr = br[k], si = bi[k];
        for (int j = k + 1; j < m; j++) {
            double xr = br[j], xi = bi[j]; double acr = Ar[k*m+j], aci = Ai[k*m+j];
            sr = sr - (acr*xr - aci*xi); si = si - (acr*xi + aci*xr);
        }
        double dr = Ar[k*m+k], di = Ai[k*m+k]; double den = dr*dr + di*di;
        br[k] = (sr*dr + si*di) / den; bi[k] = (si*dr - sr*di) / den;
    }
    free(piv);
    return 0;
}

static double* transpose_to_cm(const double* Ad, long n) {
    double* cm = (double*)malloc(sizeof(double) * n * n);
    for (long j = 0; j < n; j++) for (long i = 0; i < n; i++) cm[j*n + i] = Ad[i*n + j];
    return cm;
}

static PyObject* fast_dominant_eig(PyObject* self, PyObject* Aobj) {
    PyArrayObject* Aarr = (PyArrayObject*)PyArray_FROMANY(Aobj, NPY_DOUBLE, 2, 2,
        NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (!Aarr) return NULL;
    long n = (long)PyArray_DIM(Aarr, 0);
    if (PyArray_DIM(Aarr, 1) != n || n < 1 || n > 4096) { Py_DECREF(Aarr); PyErr_SetString(PyExc_ValueError, "non-square"); return NULL; }
    double* Ad = (double*)PyArray_DATA(Aarr);

    double* cm = transpose_to_cm(Ad, n);
    double* wr = (double*)malloc(sizeof(double) * n);
    double* wi = (double*)malloc(sizeof(double) * n);
    int info;
    Py_BEGIN_ALLOW_THREADS
    info = scipy_LAPACKE_dgeev64_(COL_MAJOR, 'N', 'N', n, cm, n, wr, wi, NULL, 1, NULL, 1);
    Py_END_ALLOW_THREADS
    if (info != 0) { free(cm); free(wr); free(wi); Py_DECREF(Aarr); PyErr_SetString(PyExc_RuntimeError, "dgeev failed"); return NULL; }

    long idx = 0; double best = -1.0;
    for (long i = 0; i < n; i++) { double v = wr[i]*wr[i] + wi[i]*wi[i]; if (v > best) { best = v; idx = i; } }
    double lamr = wr[idx], lami = wi[idx];

    double* xre = (double*)malloc(sizeof(double) * n);
    double* xim = (double*)malloc(sizeof(double) * n);

    int ok = 0;
    if (n == 1) { xre[0] = 1.0; xim[0] = 0.0; ok = 1; }
    else {
        int m = (int)n - 1;
        double* Mr = (double*)malloc(sizeof(double) * n * n);
        double* Mi = (double*)malloc(sizeof(double) * n * n);
        for (long i = 0; i < n; i++) for (long j = 0; j < n; j++) {
            if (i == j) { Mr[i*n+j] = Ad[i*n+j] - lamr; Mi[i*n+j] = -lami; }
            else { Mr[i*n+j] = Ad[i*n+j]; Mi[i*n+j] = 0.0; }
        }
        long p = 0; double pc = -1.0;
        for (long j = 0; j < n; j++) { double s = 0; for (long i = 0; i < n; i++) { double a = Mr[i*n+j], b = Mi[i*n+j]; s += a*a + b*b; } if (s > pc) { pc = s; p = j; } }
        double* Br = (double*)malloc(sizeof(double) * m * m);
        double* Bi = (double*)malloc(sizeof(double) * m * m);
        double* brr = (double*)malloc(sizeof(double) * m);
        double* bri = (double*)malloc(sizeof(double) * m);
        for (long kk = 0; kk < m; kk++) {
            long r = (kk < p) ? kk : kk + 1;
            brr[kk] = -Mr[r*n + p]; bri[kk] = -Mi[r*n + p];
            for (long ll = 0; ll < m; ll++) { long cc = (ll < p) ? ll : ll + 1; Br[kk*m+ll] = Mr[r*n+cc]; Bi[kk*m+ll] = Mi[r*n+cc]; }
        }
        int luok = cplx_lu_solve(Br, Bi, brr, bri, m);
        if (luok == 0) {
            for (long kk = 0; kk < m; kk++) { long r = (kk < p) ? kk : kk + 1; xre[r] = brr[kk]; xim[r] = bri[kk]; }
            xre[p] = 1.0; xim[p] = 0.0;
            double s = 0; for (long i = 0; i < n; i++) s += xre[i]*xre[i] + xim[i]*xim[i];
            double inv = 1.0 / sqrt(s);
            for (long i = 0; i < n; i++) { xre[i] *= inv; xim[i] *= inv; }
            double maxr = 0;
            for (long i = 0; i < n; i++) {
                double sr = 0, si = 0;
                for (long j = 0; j < n; j++) { double a = Ad[i*n+j]; sr += a*xre[j]; si += a*xim[j]; }
                double rr = sr - lamr*xre[i] + lami*xim[i];
                double ri = si - lamr*xim[i] - lami*xre[i];
                double v = sqrt(rr*rr + ri*ri); if (v > maxr) maxr = v;
            }
            if (maxr > 1e-6) luok = -1;
        }
        if (luok == 0) ok = 1;
        free(Mr); free(Mi); free(Br); free(Bi); free(brr); free(bri);
    }

    if (!ok) {
        double* cm2 = transpose_to_cm(Ad, n);
        double* vr = (double*)malloc(sizeof(double) * n * n);
        Py_BEGIN_ALLOW_THREADS
        info = scipy_LAPACKE_dgeev64_(COL_MAJOR, 'N', 'V', n, cm2, n, wr, wi, NULL, 1, vr, n);
        Py_END_ALLOW_THREADS
        if (info != 0) { free(cm2); free(vr); free(cm); free(wr); free(wi); free(xre); free(xim); Py_DECREF(Aarr); PyErr_SetString(PyExc_RuntimeError, "dgeev V failed"); return NULL; }
        long idx2 = 0; double bb = -1.0;
        for (long i = 0; i < n; i++) { double v = wr[i]*wr[i] + wi[i]*wi[i]; if (v > bb) { bb = v; idx2 = i; } }
        for (long i = 0; i < n; i++) xre[i] = vr[idx2*n + i];
        if (wi[idx2] > 0) { for (long i = 0; i < n; i++) xim[i] = vr[(idx2+1)*n + i]; }
        else if (wi[idx2] < 0) { for (long i = 0; i < n; i++) xim[i] = -vr[(idx2-1)*n + i]; }
        else { for (long i = 0; i < n; i++) xim[i] = 0.0; }
        double s = 0; for (long i = 0; i < n; i++) s += xre[i]*xre[i] + xim[i]*xim[i];
        double inv = 1.0 / sqrt(s); for (long i = 0; i < n; i++) { xre[i] *= inv; xim[i] *= inv; }
        lamr = wr[idx2]; lami = wi[idx2];
        free(cm2); free(vr);
    }

    npy_intp shape[1] = { (npy_intp)n };
    PyArrayObject* xvec = (PyArrayObject*)PyArray_NewFromDescr(&PyArray_Type,
        PyArray_DescrFromType(NPY_COMPLEX128), 1, shape, NULL, NULL, 0, NULL);
    double* xv = (double*)PyArray_DATA(xvec);
    for (long i = 0; i < n; i++) { xv[2*i] = xre[i]; xv[2*i+1] = xim[i]; }
    PyObject* lamobj = PyComplex_FromDoubles(lamr, lami);
    PyObject* tup = PyTuple_Pack(2, lamobj, (PyObject*)xvec);
    Py_DECREF(xvec);
    free(cm); free(wr); free(wi); free(xre); free(xim);
    Py_DECREF(Aarr);
    return tup;
}

static PyMethodDef Methods[] = {
    {"fast_dominant_eig", fast_dominant_eig, METH_O, "dominant eigenpair"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef mod = { PyModuleDef_HEAD_INIT, "_fasteig", NULL, -1, Methods };
PyMODINIT_FUNC PyInit__fasteig(void) {
    import_array();
    return PyModule_Create(&mod);
}
