import numpy as np

try:
    import _fasteig
    _FAST = _fasteig.fast_dominant_eig
except Exception:
    _FAST = None


def find_dominant_eigenvalue_and_eigenvector(A: np.ndarray):
    """Find the dominant eigenvalue (largest magnitude) and its eigenvector
    of a general real square matrix. The eigenpair may be complex.
    """
    if _FAST is not None:
        try:
            return _FAST(A)
        except Exception:
            pass
    eigenvalues, eigenvectors = np.linalg.eig(A)
    idx = int(np.argmax(np.abs(eigenvalues)))
    return eigenvalues[idx], eigenvectors[:, idx]
